def calc(n,eq,tk,te,lines,ans,k='',e='',sub=''):
 steps=[(M(x),M(x)) for x in lines]
 if k:steps.append((k,e))
 add(n,M(eq)+' '+tk,M(eq)+' '+te,steps,M(ans),M(ans),'영점·교점과 각도 구간을 확인하고 적분 또는 도함수를 원래 식에서 검산했다.','Zeros, intersections, and angular intervals were checked, and integrals or derivatives verified against the original equations.',sub)
def area(n,eq,tk,te,expr,a,b,factor=1,detailk='',detaile=''):
 v=S.simplify(factor*S.integrate(expr,(t,a,b)))
 integral=rf'A={S.latex(S.sympify(factor))}\int_{{{S.latex(S.sympify(a))}}}^{{{S.latex(S.sympify(b))}}}{S.latex(expr)}\,dt'
 calc(n,eq,tk,te,[r'A=\frac12\int(r_{\rm outer}^2-r_{\rm inner}^2)\,d\theta',integral],rf'A={S.latex(v)}',detailk,detaile)
 return v
