def quad(expr,a,b):
 f=S.lambdify(t,expr,'mpmath');aa=mp.mpf(str(S.N(a,40)));bb=mp.mpf(str(S.N(b,40)))
 v=mp.quad(f,[aa+(bb-aa)*i/80 for i in range(81)])
 with mp.workdps(55):w=mp.quad(f,[aa+(bb-aa)*i/160 for i in range(161)])
 assert abs(v-w)<mp.mpf('1e-15'),(v,w)
 return float(v)
for n,eq,r,a,b in [(59,r'r=\cos2\theta',S.cos(2*t),-S.pi/4,S.pi/4),(60,r'r=\tan\theta,\quad\pi/6\le\theta\le\pi/3',S.tan(t),S.pi/6,S.pi/3),(61,r'r=\sin(6\sin\theta)',S.sin(6*S.sin(t)),0,S.pi),(62,r'r=\sin(\theta/4)',S.sin(t/4),0,8*S.pi)]:
 expr=S.sqrt(r*r+S.diff(r,t)**2);v=quad(expr,a,b)
 calc(n,eq,'곡선 길이를 소수 넷째 자리까지 구하라.'+(' 고리 하나만 계산한다.' if n==59 else ''),'Find the curve length to four decimal places.'+(' Use only one loop.' if n==59 else ''),[rf'{S.latex(a)}\le\theta\le{S.latex(b)}',rf'L=\int_{{{S.latex(a)}}}^{{{S.latex(b)}}}{S.latex(expr.subs(t,S.Symbol(r'\theta')))}\,d\theta'],rf'L\approx{v:.4f}','정밀도와 분할을 늘린 수치 적분을 대조했다. 반복되는 궤적은 한 번만 센다.','Quadrature was repeated with greater precision and subdivision; repeated traces are counted once.')
 if n>=61:svg(n,'Complete trace for numerical arc length',[('curve',polar(S.lambdify(t,r,'math'),float(a),float(b),6000))])
for n,eq,r,a in [(63,r'r=2\cos\theta,\quad\theta=\pi/3',2*S.cos(t),S.pi/3),(64,r'r=2+\sin3\theta,\quad\theta=\pi/4',2+S.sin(3*t),S.pi/4),(65,r'r=1/\theta,\quad\theta=\pi',1/t,S.pi),(66,r'r=\sin\theta+2\cos\theta,\quad\theta=\pi/2',S.sin(t)+2*S.cos(t),S.pi/2),(67,r'r=\cos2\theta,\quad\theta=\pi/4',S.cos(2*t),S.pi/4),(68,r'r=1+2\cos\theta,\quad\theta=\pi/3',1+2*S.cos(t),S.pi/3)]:
 dx=S.diff(r*S.cos(t),t);dy=S.diff(r*S.sin(t),t);v=S.simplify(dy.subs(t,a)/dx.subs(t,a))
